  "<b>Abandonner cette Épreuve ?</b><br>Elle comptera comme perdue pour aujourd’hui.": "<b>Desistir desta Prova?</b><br>Ela contará como perdida hoje.",
  "<b>Abyssal · Remous abyssal</b>{e0}": "<b>Abissal · Redemoinho abissal</b>{e0}",
  "<b>Adversaires et défi</b>{e0}": "<b>Adversários e desafio</b>{e0}",
  "<b>Alliées cette semaine</b> : Infernal et Nécrotique<br>{e0}": "<b>Aliadas nesta semana</b>: Infernal e Necrótica<br>{e0}",
  "<b>Annonces</b> : les grosses attaques des gardiens et des élites s’affichent sur la frise, à côté de leur portrait. Brise-les avant qu’ils jouent pour les annuler.": "<b>Anúncios</b>: os grandes ataques dos guardiões e das elites aparecem na barra de turnos, ao lado do retrato. Quebre-os antes que ajam para cancelá-los.",
  "<b>Artificiel · Verrou artificiel</b>{e0}": "<b>Artificial · Trava artificial</b>{e0}",
  "<b>Assaut conjoint</b> ({0} Ferveur, une fois par combat) : sur un ennemi Fêlé, Brisé ou Marqué, ta créature et celle qui joue juste après frappent ensemble (×{1} chacune), avec l’effet de leurs deux rôles. L’alliée appelée perd son tour à venir. C’est aussi un coup de rupture.": "<b>Ataque conjunto</b> ({0} Fervor, uma vez por combate): em um inimigo Rachado, Quebrado ou Marcado, sua criatura e a que joga logo depois atacam juntas (×{1} cada), com o efeito dos dois papéis. A aliada chamada perde o próximo turno. Também é um golpe de ruptura.",
  "<b>Assaut conjoint</b>{e0}": "<b>Ataque conjunto</b>{e0}",
  "<b>Attaque</b> (gratuite, +{0} PA) : dégâts fiables, +{1} Ferveur. <b>Défense</b> (gratuite, +{2} PA) : -{3} % de dégâts jusqu’à son prochain tour. <b>Passer</b> : elle ne fait rien. <b>Permuter</b> (une fois par tour) : une créature de la réserve prend sa place et joue tout de suite ; PV, PA et états sont gardés, et la réserve récupère {4} % de PV par tour. En entrant, elle déclenche un petit effet lié à son rôle (bouclier, soin, Ferveur, ralentissement…).": "<b>Ataque</b> (grátis, +{0} PA): dano confiável, +{1} Fervor. <b>Defesa</b> (grátis, +{2} PA): -{3}% de dano até o próximo turno. <b>Passar</b>: ela não faz nada. <b>Trocar</b> (uma vez por turno): uma criatura da reserva assume o lugar e joga na hora; PV, PA e estados são mantidos, e a reserva recupera {4}% dos PV por turno. Ao entrar, ela ativa um pequeno efeito ligado ao seu papel (escudo, cura, Fervor, lentidão…).",
  "<b>Bien miser</b>{e0}": "<b>Apostar bem</b>{e0}",
  "<b>Booster de l’Abysse</b>{e0}": "<b>Pacote do Abismo</b>{e0}",
  "<b>Booster gratuit du jour</b><small>Il se garde : jusqu’à {0} en réserve si tu ne l’ouvres pas tout de suite.</small>": "<b>Pacote grátis do dia</b><small>Ele fica guardado: até {0} na reserva se você não abrir na hora.</small>",
  "<b>Booster premium</b>{e0}": "<b>Pacote premium</b>{e0}",
  "<b>Booster standard</b>{e0}": "<b>Pacote padrão</b>{e0}",
  "<b>Brisure</b> : en visant une élite ou un gardien, la cible affiche la Brisure que ton coup va infliger (◆), et « BRISE ! » quand il va le briser. Un seul coup ne retire jamais plus de {0} % des PV d’un gardien.": "<b>Quebra</b>: ao mirar uma elite ou um guardião, o alvo mostra a Quebra que seu golpe vai causar (◆), e “QUEBRA!” quando ele vai quebrá-lo. Um único golpe nunca tira mais de {0}% dos PV de um guardião.",
