  "<b>Terreur du Rêveur Sous la Fosse</b> : Ralentit tous les ennemis et +{0} Ferveur.": "<b>Terror do Sonhador sob a Fossa</b>: Deixa todos os inimigos lentos e +{0} Fervor.",
  "<b>Terreur du {n0}</b> : Ralentit tous les ennemis et +{0} Ferveur.": "<b>Terror de {n0}</b>: Deixa todos os inimigos lentos e +{0} Fervor.",
