  "<b>Voir une carte</b> : garde le doigt appuyé sur une carte (ennemie ou alliée) pour ouvrir sa fiche : PV, attaque, intention, passifs. Un toucher court sur un ennemi attaque toujours directement.": "<b>Ver uma carta</b>: mantenha o dedo pressionado em uma carta (inimiga ou aliada) para abrir a ficha: PV, ataque, intenção, passivas. Um toque curto em um inimigo sempre ataca direto.",
