  "Accueil": "Início",
  "Accumule le poison, puis Contagion pour le propager.": "Acumule veneno e depois use Contágio para espalhá-lo.",
  "Accumule {0} poisons ou plus, puis Raz-de-marée : le poison explose (× {1} en dégâts d’un coup).": "Acumule {0} venenos ou mais e depois use Maremoto: o veneno explode (× {1} de dano de uma vez).",
  "Acheter": "Comprar",
  "Acheter {e0}": "Comprar {e0}",
  "Acheter · {0}": "Comprar · {0}",
  "Acheter · {0} €": "Comprar · € {0}",
  "Achetée une fois, la finition se pose sur autant de cartes que tu veux, depuis la fiche de chaque carte. Elle ne change rien à leurs valeurs.": "Comprado uma vez, o acabamento pode ser aplicado em quantas cartas você quiser, pela ficha de cada carta. Ele não muda os valores delas.",
  "Achète des boosters avec tes <b>éclats</b>, ou ouvre ceux qu’on t’offre : un <b>booster gratuit chaque jour</b> (il se garde : jusqu’à {0} en réserve si tu manques un jour). Déchire le paquet du doigt, puis retourne les cartes.<br><br>Une carte peut sortir dans une <b>finition rare</b> : <b>argentée</b> (gravée à la pointe d’argent), <b>enluminée</b> (une page dorée du Bestiaire) ou <b>abyssale</b> (envahie par l’encre de l’Abysse, la plus rare). Tu peux aussi <b>sublimer</b> une carte que tu possèdes vers la finition suivante, contre des cendres (Collection → Forge → Fournaise, ou fiche de la carte, onglet Rareté).": "Compre pacotes com seus <b>Fragmentos</b>, ou abra os que você ganhar: um <b>pacote grátis por dia</b> (ele fica guardado: até {0} na reserva se você perder um dia). Rasgue o pacote com o dedo e depois vire as cartas.<br><br>Uma carta pode sair com um <b>acabamento raro</b>: <b>prateado</b> (gravado em ponta de prata), <b>iluminado</b> (uma página dourada do Bestiário) ou <b>abissal</b> (invadido pela tinta do Abismo, o mais raro). Você também pode <b>sublimar</b> uma carta que possui para o acabamento seguinte, em troca de Cinzas (Coleção → Forja → Fornalha, ou ficha da carta, aba Raridade).",
  "Achève les cibles empoisonnées, et son poison passe à un voisin (Éveil).": "Finaliza alvos envenenados, e o veneno dela passa para um vizinho (Despertar).",
  "Achève {0} ennemis avec elle": "Finalize {0} inimigos com ela",
  "Achève-le d’un coup, ou gèle-le.": "Finalize-o de um golpe, ou congele-o.",
