  "Activer le Mode Créateur": "Ativar o Modo Criador",
  "Adapte-toi à chaque Loi : brise-le sous la Loi du fer, ménage tes compétences sous la Loi du silence.": "Adapte-se a cada Lei: quebre-o sob a Lei do Ferro, poupe suas habilidades sob a Lei do Silêncio.",
