  "Adversaires à venir ({0})": "Próximos adversários ({0})",
  "Affaiblis-les tous les deux avant d’en abattre un, puis achève le second très vite.": "Enfraqueça os dois antes de derrubar um, e depois finalize o segundo bem rápido.",
  "Affaiblit les cibles résistantes avec le poison.": "Enfraquece alvos resistentes com veneno.",
  "Affiche directement le récapitulatif, sans révéler les cartes une par une.": "Mostra o resumo direto, sem revelar as cartas uma a uma.",
  "Afficher": "Mostrar",
