  "Ajoute des joueurs grâce à leur pseudo et découvre leur collection, leurs succès et leurs exploits.": "Adicione jogadores pelo apelido e descubra a coleção, as conquistas e as façanhas deles.",
  "Ajoute des joueurs grâce à leur pseudo et découvre leur collection.": "Adicione jogadores pelo apelido e descubra a coleção deles.",
  "Ajoute d’abord une créature en réserve pour faire l’échange.": "Primeiro coloque uma criatura na reserva para fazer a troca.",
