  "Ajoutée à tes favoris : elle ne pourra pas être brûlée par erreur.": "Adicionada às favoritas: ela não poderá ser queimada por engano.",
  "Aller au Butin": "Ir ao Espólio",
  "Aller à la Fournaise": "Ir à Fornalha",
  "Aller à l’étage": "Ir ao andar",
  "Allégés": "Leves",
  "Allégés : moins de particules, ni secousses de caméra ni éclairs, décor sobre. À essayer si les combats saccadent.": "Leves: menos partículas, sem tremor de câmera nem clarões, cenário simples. Experimente se os combates travarem.",
  "Alors… le Néant peut perdre une enchère.": "Então… o Vazio pode perder um leilão.",
  "Alors… le Néant peut perdre.": "Então… o Vazio pode perder.",
