  "Bats Maître Orvel pour l’affronter": "Vença Mestre Orvel para enfrentá-lo",
  "Bats Sœur Vesna pour l’affronter": "Vença Irmã Vesna para enfrentá-lo",
  "Bats chaque adversaire pour débloquer le suivant. Un défi du jour t’attend aussi.": "Vença cada adversário para desbloquear o próximo. Um desafio do dia também espera por você.",
  "Bats d’abord l’adversaire précédent.": "Vença primeiro o adversário anterior.",
  "Bats ton premier gardien dans la Descente : il viendra ici. · force de l’étage {0}": "Vença seu primeiro guardião na Descida: ele virá para cá. · poder do andar {0}",
  "Bats tous les adversaires en revanche implacable aux Duels des Sceaux.": "Vença todos os adversários em revanche implacável nos Duelos dos Selos.",
  "Bats {n0} pour l’affronter": "Vença {n0} para enfrentá-lo",
  "Bats-le d’abord une fois.": "Vença-o uma vez primeiro.",
  "Battue abyssale": "Batida abissal",
  "Battue ardente": "Batida ardente",
  "Battue céleste": "Batida celestial",
  "Battue funèbre": "Batida fúnebre",
  "Battue mécanique": "Batida mecânica",
  "Battue sauvage": "Batida selvagem",
  "Bellérophon la tua du haut de Pégase. Ses trois têtes ne se sont jamais mises d’accord sur sa mort.": "Belerofonte a matou do alto de Pégaso. Suas três cabeças nunca concordaram sobre a própria morte.",
  "Bestiaire": "Bestiário",
  "Bien miser": "Apostar bem",
  "Bienvenue": "Boas-vindas",
  "Bienvenue dans MA salle des ventes. Tout se paie, ici.": "Bem-vindo à MINHA casa de leilões. Aqui, tudo tem preço.",
  "Bienvenue dans l’Abysse": "Bem-vindo ao Abismo",
