  "Bloqué par le Verrou artificiel : rien ne se passe.": "Bloqueado pela Trava artificial: nada acontece.",
  "Bonne mémoire, et il suit les cartes qui bougent.": "Boa memória, e ele segue as cartas que se movem.",
