  "Bouclier": "Escudo",
  "Bouclier : bloque le prochain coup.": "Escudo: bloqueia o próximo golpe.",
  "Bouclier : bloque un coup": "Escudo: bloqueia um golpe",
  "Bouclier béni": "Escudo abençoado",
  "Bouclier double": "Escudo duplo",
  "Bouclier double de Héphaïstos": "Escudo duplo de Hefesto",
  "Bouclier sur tes créatures au combat, dégel, et +{0} PA pour chacune.": "Escudo nas suas criaturas em combate, descongelamento e +{0} PA para cada uma.",
  "Bourdonnement d’acier": "Zumbido de aço",
  "Braise sacrée": "Brasa sagrada",
  "Braises de pureté": "Brasas da pureza",
  "Bram Stoker l’a rendu célèbre. Il aurait préféré rester une rumeur.": "Bram Stoker o tornou famoso. Ele preferia ter continuado um boato.",
  "Brasier": "Braseiro",
  "Bris de glace": "Estilhaço de gelo",
  "Bris de glace !": "Estilhaço de gelo!",
  "Bris de glace (gelée)": "Estilhaço de gelo (congelada)",
  "Brise le miroir avec un petit coup (une attaque faible, une créature robuste), puis frappe fort. Le poison passe à travers.": "Quebre o espelho com um golpe fraco (um ataque fraco, uma criatura resistente) e depois bata forte. O veneno passa.",
  "Brise l’ennemi au moins une fois.": "Quebre o inimigo pelo menos uma vez.",
  "Brise sa garde ou interromps sa charge.": "Quebre a guarda dele ou interrompa a carga.",
  "Brise-garde": "Quebra-guarda",
  "Brise-la ou gèle-la pendant que la ruche s’éveille, esquive l’Essaim, et purifie le poison (Prière).": "Quebre-a ou congele-a enquanto a colmeia desperta, esquive do Enxame e purifique o veneno (Prece).",
  "Brise-le ou gèle-le pendant qu’il remonte le temps, ou garde tes plus gros coups pour juste après.": "Quebre-o ou congele-o enquanto ele volta no tempo, ou guarde seus golpes mais fortes para logo depois.",
  "Brise-le pendant le Chant, esquive la Complainte et dépense ta Ferveur avant qu’elle ne tombe. Une Brisure retient la marée un tour.": "Quebre-o durante o Canto, esquive do Lamento e gaste seu Fervor antes que ele caia. Uma Quebra segura a maré por um turno.",
  "Briseur": "Quebrador",
  "Briseur de sceaux": "Quebrador de selos",
  "Briseur d’Échos": "Quebrador de Ecos",
  "Briseurs de machines": "Quebradores de máquinas",
  "Brisure": "Quebra",
  "Brisures": "Quebras",
  "Brisé": "Quebrado",
  "Brisé : +{0} % de dégâts subis, +{1} aux jets": "Quebrado: +{0}% de dano sofrido, +{1} nas rolagens",
  "Brisé : +{0} % de dégâts subis, +{1} aux jets.": "Quebrado: +{0}% de dano sofrido, +{1} nas rolagens.",
  "Brisé : passe son tour": "Quebrado: perde o turno",
  "Brisée": "Quebrada",
  "Brisée, elle rétrécit": "Quebrada, ela encolhe",
  "Brume abyssale": "Névoa abissal",
  "Brume ardente": "Névoa ardente",
  "Brume spectrale et visages d’esprits.": "Névoa espectral e rostos de espíritos.",
  "Brèche": "Brecha",
  "Brèche : le prochain coup d’un autre allié perce son bouclier, +{0} % de dégâts, +{1} Brisure": "Brecha: o próximo golpe de outro aliado perfura o escudo dele, +{0}% de dano, +{1} de Quebra",
  "Brèche exploitée !": "Brecha explorada!",
  "Brèche sur la cible et bouclier sur ta créature la plus blessée": "Brecha no alvo e escudo na sua criatura mais ferida",
  "Brûle des cartes pour des cendres. Les cendres font monter tes créatures de niveau (Forge → Renforcer).": "Queime cartas para ganhar Cinzas. As Cinzas sobem o nível das suas criaturas (Forja → Fortalecer).",
  "Brûle des cartes pour obtenir des <b>cendres</b>. <b>Tout brûler</b> ne prend que tes doublons : tu gardes toujours un exemplaire de chaque finition.<br><br>Plus la carte est rare, plus elle donne de cendres, et les finitions rares bien plus encore. Tu peux aussi brûler ta dernière copie, après confirmation.": "Queime cartas para obter <b>Cinzas</b>. <b>Queimar tudo</b> só pega suas repetidas: você sempre guarda um exemplar de cada acabamento.<br><br>Quanto mais rara a carta, mais Cinzas ela dá, e os acabamentos raros muito mais. Você também pode queimar sua última cópia, após confirmar.",
  "Brûle tes doublons dans la Fournaise pour gagner des cendres.": "Queime suas repetidas na Fornalha para ganhar Cinzas.",
  "Brûle tes doublons dans la Fournaise.": "Queime suas repetidas na Fornalha.",
