  "Chimères, bêtes mythologiques, lycanthropes et prédateurs primitifs. La Forêt Première couvrait tout avant les villes ; elle a seulement reculé, et elle se souvient de chaque arbre abattu.": "Quimeras, feras mitológicas, licantropos e predadores primitivos. A Floresta Primeira cobria tudo antes das cidades; ela apenas recuou, e se lembra de cada árvore derrubada.",
