  "Classement du lundi au dimanche : tes tirages s’additionnent. Les coffres sont donnés s’il y a au moins {0} participants, et arrivent le lundi suivant quand tu ouvres le jeu. Chaque tirage rapporte aussi <b>{1} éclats</b>.": "Ranking de segunda a domingo: seus sorteios se somam. Os baús são dados se houver pelo menos {0} participantes, e chegam na segunda seguinte quando você abre o jogo. Cada sorteio também rende <b>{1} Fragmentos</b>.",
