  "Colle un code de sauvegarde ABYSSAL ou choisis un fichier. <b>La progression actuelle de cet appareil sera remplacée.</b>": "Cole um código de salvamento ABYSSAL ou escolha um arquivo. <b>O progresso atual deste aparelho será substituído.</b>",
