  "Compte chaque carte sortie, sans jamais se tromper.": "Conta cada carta que sai, sem nunca errar.",
  "Compte confirmé : tu es connecté, ta partie sera sauvegardée en ligne.": "Conta confirmada: você está conectado, sua partida será salva on-line.",
  "Compte créé ! Un e-mail de confirmation t’a été envoyé : touche son lien, puis reviens te connecter ici.": "Conta criada! Um e-mail de confirmação foi enviado: toque no link e depois volte aqui para entrar.",
  "Compte créé : ta partie est maintenant sauvegardée en ligne.": "Conta criada: sua partida agora está salva on-line.",
  "Compte créé et connecté : ta partie en ligne est chargée.": "Conta criada e conectada: sua partida on-line foi carregada.",
  "Compte les cartes déjà tirées, pèse chaque risque, se presse quand tu approches du but.": "Conta as cartas já tiradas, pesa cada risco, se apressa quando você se aproxima do objetivo.",
  "Compte les lots qui restent, avec des écarts difficiles à prévoir.": "Conta os lotes que restam, com variações difíceis de prever.",
  "Compte les lots qui restent, et bluffe parfois.": "Conta os lotes que restam, e às vezes blefa.",
