  "Concentration": "Concentração",
  "Concentration…": "Concentração…",
  "Concentre son énergie, puis frappe toute ton équipe.": "Concentra sua energia e depois atinge toda a sua equipe.",
  "Concentre tes coups sur l’élite ou le gardien pour le briser : il perd son tour.": "Concentre seus golpes na elite ou no guardião para quebrá-lo: ele perde o turno.",
  "Condamne ta créature la plus affaiblie : il l’exécutera au tour suivant. Permute-la en réserve, défends-la, ou brise-le.": "Condena sua criatura mais enfraquecida: ele a executará no turno seguinte. Troque-a para a reserva, defenda-a ou quebre-o.",
  "Condamné à porter le ciel. Il a cessé de compter les siècles, pas les étoiles.": "Condenado a sustentar o céu. Parou de contar os séculos, não as estrelas.",
