  "Crée ton compte pour entrer dans l’Abysse : ta collection est sauvegardée en ligne, tu la retrouves sur n’importe quel appareil, et tu entres dans les classements.": "Crie sua conta para entrar no Abismo: sua coleção fica salva on-line, você a encontra em qualquer aparelho e entra nos rankings.",
  "Crée un compte": "Crie uma conta",
  "Crée un compte gratuit pour ne jamais la perdre (changement de téléphone, appli supprimée).": "Crie uma conta grátis para nunca perdê-la (troca de telefone, aplicativo apagado).",
  "Créer mon compte": "Criar minha conta",
