  "Donne un nom à cette équipe.": "Dê um nome a esta equipe.",
  "Donne à une carte que tu possèdes sa finition suivante (argentée, puis enluminée, puis abyssale) contre des cendres. Tes favorites et ton équipe d’abord. Tu peux en sublimer <b>{0}</b> maintenant.": "Dê a uma carta que você possui o acabamento seguinte (prateado, depois iluminado, depois abissal) em troca de Cinzas. Suas favoritas e sua equipe primeiro. Você pode sublimar <b>{0}</b> agora.",
