  "Début du combat<br><b>Lucifer, l’Étoile du Matin</b> : Égide<br><b>Le Rêveur Sous la Fosse</b> : Engloutir, Augure<br><b>Métatron, la Voix du Trône</b> : Égide": "Início do combate<br><b>Lúcifer, a Estrela da Manhã</b>: Égide<br><b>O Sonhador sob a Fossa</b>: Engolir, Augúrio<br><b>Metatron, a Voz do Trono</b>: Égide",
