  "Démons": "Demônios",
  "Démons, seigneurs des cercles, pactes et corruption. La Géhenne est une cité de cuivre bâtie sur un fleuve de feu, où chaque promesse est consignée et chaque dette finit par être réclamée.": "Demônios, senhores dos círculos, pactos e corrupção. A Geena é uma cidade de cobre construída sobre um rio de fogo, onde cada promessa é registrada e cada dívida acaba sendo cobrada.",
  "Dépense sans compter, surtout pour une famille de trois.": "Gasta sem contar, principalmente por uma família de três.",
  "Désactiver le Mode Créateur": "Desativar o Modo Criador",
  "Désignation abyssale": "Designação abissal",
  "Désignation du Roi des Sceaux": "Designação do Rei dos Selos",
  "Désigne ta créature la plus affaiblie : pendant {0} tours, tous les ennemis la visent et lui font +{1} % de dégâts. Mets-la en réserve ou protège-la.": "Designa sua criatura mais enfraquecida: durante {0} turnos, todos os inimigos a miram e causam +{1}% de dano nela. Coloque-a na reserva ou proteja-a.",
  "Désigne une proie": "Designa uma presa",
  "Désigne une proie : Désigne ta créature la plus affaiblie : pendant {0} tours, tous les ennemis la visent et lui font +{1} % de dégâts. Mets-la en réserve ou protège-la.": "Designa uma presa: Designa sua criatura mais enfraquecida: durante {0} turnos, todos os inimigos a miram e causam +{1}% de dano nela. Coloque-a na reserva ou proteja-a.",
