  "Empoisonne ta créature la plus dangereuse.": "Envenena sua criatura mais perigosa.",
  "Empoisonnement": "Envenenamento",
  "Empoisonneur": "Envenenador",
  "Empoisonneur maudit": "Envenenador maldito",
  "Empoisonneur prophétique": "Envenenador profético",
  "Empoisonneur terrifiant": "Envenenador aterrorizante",
  "Empoisonneur vampirique": "Envenenador vampírico",
  "Empoisonneur venimeux": "Envenenador peçonhento",
  "Empoisonneur éternel": "Envenenador eterno",
  "En Bretagne, le dernier mort de l’année devient l’Ankou de l’année suivante. C’est un emploi stable.": "Na Bretanha, o último morto do ano se torna o Ankou do ano seguinte. É um emprego estável.",
  "En attente": "Pendente",
  "En cours": "Em andamento",
  "En cours ({0}/{1}).": "Em andamento ({0}/{1}).",
  "En cours.": "Em andamento.",
  "En créant un compte, tu acceptes la {e0}. Il faut avoir {0} ans ou plus.": "Ao criar uma conta, você aceita a {e0}. É preciso ter {0} anos ou mais.",
  "En défense": "Em defesa",
  "En défense : -{0} % de dégâts.": "Em defesa: -{0}% de dano.",
  "En entrant": "Ao entrar",
  "En haut : {0} + {1} = {2}. À gauche : {3} + {4} = {5}. Deux fois la même somme.": "Em cima: {0} + {1} = {2}. À esquerda: {3} + {4} = {5}. Duas vezes a mesma soma.",
  "En haut de l'écran et au classement": "No topo da tela e no ranking",
  "En haut du combat, un <b>objectif</b> facultatif (cible dorée) : sans perte, en peu de tours, une parade, une Brisure… Touche-le pour le lire.<br><br>Réussi et combat gagné : des <b>éclats</b> en plus et <b>+{0} Ferveur</b> pour la suite du chapitre. Manqué : rien de perdu.": "No topo do combate, um <b>objetivo</b> opcional (alvo dourado): sem perdas, em poucos turnos, uma defesa, uma Quebra… Toque nele para ler.<br><br>Cumprido e combate vencido: <b>fragmentos</b> extras e <b>+{0} Fervor</b> para o resto do capítulo. Falhou: nada perdido.",
  "En renaissant, soigne toute l’équipe de {0} %.": "Ao renascer, cura a equipe inteira em {0}%.",
  "En réserve": "Na reserva",
  "Encaisse et protège les plus fragiles.": "Aguenta os golpes e protege os mais frágeis.",
  "Encaisse {0} points en un seul tour.": "Acumule {0} pontos em um único turno.",
  "Encaisse à la place de ses alliés (Rempart) et tient longtemps.": "Recebe os golpes no lugar dos aliados (Baluarte) e aguenta muito tempo.",
  "Enchaînée": "Acorrentada",
  "Enchères": "Leilão",
  "Enchères à l’aveugle à trois : offre plus que les autres… sans jamais offrir pareil.": "Leilão às cegas a três: ofereça mais que os outros… sem nunca oferecer igual.",
  "Encore faim : il peut rejouer": "Ainda com fome: pode agir de novo",
  "Encore scellé": "Ainda selado",
  "Encore scellée": "Ainda selada",
  "Encore scellées": "Ainda seladas",
  "Encore scellés": "Ainda selados",
  "Encore un": "Mais um",
  "Encore une fois": "Mais uma vez",
  "Encore une. Et encore une. Tu entends l’écho ?": "Mais uma. E mais uma. Está ouvindo o eco?",
  "Encore {0} Ferveur à gagner : attaque, exploite les faiblesses, esquive, pare et brise les ennemis.": "Ainda faltam {0} de Fervor: ataque, explore as fraquezas, esquive, defenda e quebre os inimigos.",
  "Encre ardente": "Tinta ardente",
  "Encre sauvage": "Tinta selvagem",
  "Engloutie !": "Engolida!",
  "Engloutir": "Engolir",
  "Enlumineur": "Iluminador",
  "Enluminée": "Iluminado",
  "Ennemi juré des nagas, il porte Vishnu sur son dos. Rien de ce qui rampe ne lui échappe.": "Inimigo jurado dos nagas, ele carrega Vishnu nas costas. Nada que rasteja lhe escapa.",
  "Ennemis trop forts": "Inimigos fortes demais",
