  "Entraveur éternel": "Acorrentador eterno",
  "Entraveur étouffant": "Acorrentador sufocante",
  "Entraveurs (Givre-venin), Venin du chasseur.": "Acorrentadores (Gelo-veneno), Veneno do caçador.",
  "Entre deux retours en arrière, il frappe deux fois de suite.": "Entre dois retrocessos, ele golpeia duas vezes seguidas.",
  "Entre en jeu": "Entra em jogo",
  "Entre le code du créateur.": "Digite o código do criador.",
  "Entre ton mot de passe.": "Digite sua senha.",
  "Entrée en scène": "Entrada em cena",
  "Entrée fracassante": "Entrada estrondosa",
  "Environ +{0} éclats": "Cerca de +{0} fragmentos",
  "Envoyer au combat": "Enviar ao combate",
  "Envoyer le lien": "Enviar link",
  "Envoyé par Artémis pour punir un roi oublieux. Il fallut tous les héros de Grèce pour l’abattre.": "Enviado por Ártemis para punir um rei esquecido. Foram precisos todos os heróis da Grécia para abatê-lo.",
  "Ermite des sommets": "Eremita dos picos",
  "Erreur": "Erro",
  "Erreur… de calcul ? Impossible.": "Erro… de cálculo? Impossível.",
  "Erreur… d’inventaire.": "Erro… de inventário.",
  "Erreur… à… réindexer.": "Erro… a… reindexar.",
  "Esprit": "Espírito",
  "Esprit céleste": "Espírito celestial",
  "Esprit de la forêt": "Espírito da floresta",
  "Esprit des eaux": "Espírito das águas",
