  "La chair qui n’oublie pas": "A carne que não esquece",
  "La chaîne": "A linha",
  "La chose double": "A coisa dupla",
  "La cité de Dis n’a qu’une porte. Elle n’a jamais été franchie dans le bon sens.": "A cidade de Dite só tem uma porta. Ninguém jamais a atravessou no sentido certo.",
  "La clause oubliée": "A cláusula esquecida",
  "La colère d’Artémis": "A ira de Ártemis",
