  "La danseuse des nuées": "A dançarina das nuvens",
  "La dernière carte du prochain booster peut être imposée.": "A última carta do próximo pacote pode ser imposta.",
  "La dernière faim": "A última fome",
  "La dernière mer": "O último mar",
