  "Le Dragon garde l'Orient. Lui garde l'Occident, et il ne partage pas.": "O Dragão guarda o Oriente. Ele guarda o Ocidente, e não divide.",
  "Le Démon sans peau": "O Demônio sem pele",
  "Le Dévoreur": "O Devorador",
  "Le Dévoreur a mangé la crypte qu’elle gardait. Elle est restée debout dans le noir, à garder ce qui n’existe plus, et sa rancune a remplacé ses os.": "O Devorador comeu a cripta que ela guardava. Ela ficou de pé no escuro, guardando o que não existe mais, e seu rancor substituiu seus ossos.",
  "Le Dévoreur du temps": "O Devorador do tempo",
