  "Le Golem de Cendres": "O Golem de Cinzas",
  "Le Gouffre qui boit": "O Abismo que bebe",
  "Le Grand Œuvre voulait unir les contraires. Il a réussi. Le résultat a des opinions.": "A Grande Obra queria unir os opostos. Conseguiu. O resultado tem opiniões.",
  "Le Grand-Père des eaux": "O Avô das águas",
