  "Le Jumeau du Jour": "O Gêmeo do Dia",
  "Le Kojiki raconte que Susanoo l’enivra avec huit cuves de saké. Il ne boit plus.": "O Kojiki conta que Susanoo o embebedou com oito tonéis de saquê. Ele não bebe mais.",
  "Le Livre de Job dit que nul ne peut le prendre à l’hameçon. Il envie seulement ce qu’il ne peut avaler.": "O Livro de Jó diz que ninguém pode pegá-lo com anzol. Ele só inveja o que não consegue engolir.",
  "Le Livre d’Hénoch dit qu’il apprit aux humains à forger le fer. Il ne précise pas pourquoi.": "O Livro de Enoque diz que ele ensinou os humanos a forjar o ferro. Não diz por quê.",
