  "Mi-chemin. Les aiguilles des horloges reculent quand tu avances. Le gardien de ce chapitre a volé du temps aux Scelleurs, assez pour les voir vieillir et mourir. Il en a encore en réserve, et il compte bien s’en servir.": "Metade do caminho. Os ponteiros dos relógios recuam quando você avança. O guardião deste capítulo roubou tempo dos Seladores, o bastante para vê-los envelhecer e morrer. Ele ainda tem um pouco de reserva, e pretende muito bem usá-lo.",
