  "Morts-vivants, spectres, vampires, liches et faucheurs. Le Pays sans Retour s’étend sous toutes les terres : chaque tombe en est une porte, et beaucoup de portes sont mal fermées.": "Mortos-vivos, espectros, vampiros, liches e ceifadores. A Terra sem Retorno se estende sob todas as terras: cada túmulo é uma porta para ela, e muitas portas estão mal fechadas.",
