  "Mère des hivers éternels": "Mãe dos invernos eternos",
  "Mère du Soleil, de la Lune et de l’Aurore. Elle a donné l’éclat à l’or et aux yeux.": "Mãe do Sol, da Lua e da Aurora. Ela deu o brilho ao ouro e aos olhos.",
  "Méduse Funèbre, Entraveurs.": "Medusa Fúnebre, Acorrentadores.",
  "Méduse fut belle avant d’être maudite. Depuis, tout ce qui croise son regard devient pierre.": "Medusa era bela antes de ser amaldiçoada. Desde então, tudo o que cruza seu olhar vira pedra.",
  "Médée le vainquit en retirant le clou de sa cheville. Il a fait poser une serrure, depuis.": "Medeia o venceu tirando o cravo de seu tornozelo. Desde então, ele mandou pôr uma fechadura.",
