  "Même derrière un Protecteur.": "Mesmo atrás de um Protetor.",
  "Même les dieux leur demandent combien de temps il leur reste.": "Até os deuses lhes perguntam quanto tempo ainda lhes resta.",
  "Même somme avec deux voisines ou plus : elles sont capturées. Puis le Combo continue, comme pour Identique.": "Mesma soma com duas vizinhas ou mais: elas são capturadas. Depois o Combo continua, como no Igual.",
  "Même ta dernière copie : la créature quitte alors ta collection (on te demande toujours de confirmer).": "Até a sua última cópia: a criatura então sai da sua coleção (sempre pedimos que você confirme).",
  "Même un moineau trouve ses graines !": "Até um pardal encontra suas sementes!",
