  "Ne peut pas être prise pour cible tant qu’elle n’a pas attaqué.": "Não pode ser alvo enquanto não tiver atacado.",
  "Neuf jours de guerre entre les Sept Cieux et ceux qui les quittèrent. Les deux camps revendiquent la victoire. Les ruines des deux camps se ressemblent.": "Nove dias de guerra entre os Sete Céus e aqueles que os deixaram. Os dois lados reivindicam a vitória. As ruínas dos dois lados se parecem.",
