  "Née d’un œuf de coq": "Nascida de um ovo de galo",
  "Née d’un œuf pondu par un coq et couvé par un crapaud. Son regard change la vie en pierre.": "Nascida de um ovo posto por um galo e chocado por um sapo. Seu olhar transforma a vida em pedra.",
  "Nées des bûchers": "Nascidas das fogueiras",
  "Nées des bûchers · Commune": "Nascidas das fogueiras · Comum",
  "N’attaque pas ce tour-ci : Complainte au tour suivant. Gel ou Brisure l’interrompent.": "Não ataca neste turno: Lamento no turno seguinte. Gelo ou Quebra o interrompem.",
  "N’attaque pas ce tour-ci : Essaim au tour suivant. Gel ou Brisure l’interrompent.": "Não ataca neste turno: Enxame no turno seguinte. Gelo ou Quebra o interrompem.",
  "N’attaque pas ce tour-ci : Tempête de givre au tour suivant. Gel ou Brisure l’interrompent.": "Não ataca neste turno: Tempestade de gelo no turno seguinte. Gelo ou Quebra o interrompem.",
  "N’attaque pas ce tour-ci : coup chargé au tour suivant. Gèle-le ou brise-le pour l’interrompre.": "Não ataca neste turno: golpe carregado no turno seguinte. Congele-o ou quebre-o para interromper.",
  "N’oublie presque rien, et brouille sans cesse tes souvenirs.": "Não esquece quase nada, e embaralha suas lembranças sem parar.",
  "N’oublie rien, évite les malédictions et brouille tout ce que tu vois.": "Não esquece nada, evita as maldições e embaralha tudo o que você vê.",
