  "Objet maudit": "Objeto amaldiçoado",
  "Observe ton équipe : au tour suivant, il retourne contre toi la compétence annoncée. Gel ou Brisure l’interrompent.": "Observa sua equipe: no turno seguinte, volta contra você a habilidade anunciada. Gelo ou Quebra o interrompem.",
  "Obsidiennes": "Obsidianas",
  "Obsidiennes : la monnaie de l'Échoppe, achetée en euros, dépensée seulement en cosmétiques.": "Obsidianas: a moeda da Loja, comprada com dinheiro real, gasta só em cosméticos.",
