  "Pline le décrit minuscule. Les siècles l’ont fait grandir. Son regard, lui, n’a pas changé.": "Plínio o descreve minúsculo. Os séculos o fizeram crescer. Seu olhar, esse não mudou.",
  "Pline écrit que son regard tue. Heureusement, il a trop de mal à relever la tête.": "Plínio escreve que seu olhar mata. Felizmente, ele tem muita dificuldade em levantar a cabeça.",
