  "Plus assez de points d’action.": "Pontos de ação insuficientes.",
  "Plus bas, l’air gèle dans tes poumons. Une reine a offert son royaume à l’hiver pour qu’il ne change jamais, et le chapitre qui la tenait endormie est tombé à ses pieds. Elle ne veut pas te tuer : elle veut te garder.": "Mais abaixo, o ar congela em seus pulmões. Uma rainha ofereceu seu reino ao inverno para que ele nunca mudasse, e o capítulo que a mantinha adormecida caiu aos seus pés. Ela não quer matar você: quer guardar você.",
  "Plus chanceux que la moyenne.": "Mais sortudo que a média.",
  "Plus cruel que le kelpie, disent les Écossais. Ceux qui le montent ne descendent plus.": "Mais cruel que o kelpie, dizem os escoceses. Quem o monta nunca mais desce.",
  "Plus dangereux : éclats doublés, {0} bonus au choix et un talent pour une de tes créatures.": "Mais perigoso: fragmentos dobrados, {0} bônus à escolha e um talento para uma das suas criaturas.",
