  "Pour faire entrer l’une d’elles, choisis l’action <b>Permuter</b> de la créature qui joue. Touche une carte pour tout voir.": "Para colocar uma delas em jogo, escolha a ação <b>Trocar</b> da criatura da vez. Toque em uma carta para ver tudo.",
  "Pour le contrer": "Para combatê-lo",
  "Pour les anciens Égyptiens, le ba quittait la tombe chaque jour pour voir le soleil.": "Para os antigos egípcios, o ba deixava o túmulo todos os dias para ver o sol.",
  "Pour voir ce que ça donne : ces boutons ne servent qu'à l'essai. Les paliers et les prix se règlent dans {e0} (demande-moi).": "Só para ver como fica: estes botões servem apenas para teste. Os graus e os preços se ajustam em {e0} (me peça).",
  "Pourpre et sang": "Púrpura e sangue",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Abyssal donne <b>Remous abyssal</b>.": "Por quê? Cada par ativa o poder da sua facção. A facção Abissal dá <b>Redemoinho abissal</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Artificiel donne <b>Verrou artificiel</b>.": "Por quê? Cada par ativa o poder da sua facção. A facção Artificial dá <b>Trava artificial</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Céleste donne <b>Grâce céleste</b>.": "Por quê? Cada par ativa o poder da sua facção. A facção Celestial dá <b>Graça celestial</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Infernal donne <b>Regard infernal</b>.": "Por quê? Cada par ativa o poder da sua facção. A facção Infernal dá <b>Olhar infernal</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Nécrotique donne <b>Pillage des tombes</b>.": "Por quê? Cada par ativa o poder da sua facção. A facção Necrótica dá <b>Saque de túmulos</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Primordial donne <b>Souffle primordial</b>.": "Por quê? Cada par ativa o poder da sua facção. A facção Primordial dá <b>Sopro primordial</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Sauvage donne <b>Cri sauvage</b>.": "Por quê? Cada par ativa o poder da sua facção. A facção Selvagem dá <b>Grito selvagem</b>.",
