  "Purifie vite (Prière) avant que la contagion ne gagne toute l’équipe, et brise-la pendant qu’elle prépare sa vague.": "Purifique rápido (Prece) antes que o contágio tome toda a equipe, e quebre-a enquanto ela prepara sua onda.",
  "Purifiée": "Purificada",
  "Père des monstres": "Pai dos monstros",
  "Père d’Atlas et de Prométhée. Titan de la mortalité, dit-on. Il n’a jamais trouvé cela drôle.": "Pai de Atlas e de Prometeu. Titã da mortalidade, dizem. Ele nunca achou isso engraçado.",
