  "Remettre la campagne à zéro ? Le record, les gardiens vaincus et le Cauchemar repartent de rien (ta collection est gardée).": "Reiniciar a campanha? O recorde, os guardiões vencidos e o Pesadelo recomeçam do zero (sua coleção é mantida).",
  "Remettre le Codex à zéro": "Reiniciar o Códice",
  "Remettre le Codex à zéro (points, récompenses récupérées, voie enluminée) ? Les objets déjà gagnés restent.": "Reiniciar o Códice (pontos, recompensas coletadas, trilha iluminada)? Os itens já ganhos ficam.",
  "Remettre à zéro": "Reiniciar",
  "Remettre à zéro : record, gardiens vaincus et Cauchemar repartent de rien, pour revivre la campagne et ses récompenses. Ta collection, tes niveaux et tes coffres ne bougent pas.": "Reiniciar: recorde, guardiões vencidos e Pesadelo recomeçam do zero, para reviver a campanha e suas recompensas. Sua coleção, seus níveis e seus baús não mudam.",
