  "Rempart sur l’allié menacé, puis Prière : il est soigné et reçoit un bouclier. Chaque coup encaissé par le Protecteur charge sa riposte.": "Baluarte no aliado ameaçado, depois Prece: ele é curado e recebe um escudo. Cada golpe que o Protetor aguenta carrega seu revide.",
