  "Réunis ces créatures dans ton équipe et combats.": "Reúna estas criaturas na sua equipe e lute.",
  "Réunis-la avec les créatures de son mythe et combats.": "Reúna-a com as criaturas do mito dela e lute.",
  "Réussi !": "Sucesso!",
  "Réussis une combinaison : Chasse, Bris de glace, Bastion ou un Enchaînement.": "Faça uma combinação: Caçada, Gelo estilhaçado, Bastião ou um Encadeamento.",
  "Réussis une parade parfaite.": "Faça uma defesa perfeita.",
