  "Réussite partielle": "Sucesso parcial",
  "Réveillé, il frappe plus fort et prépare un coup chargé tous les trois tours.": "Desperto, ele bate mais forte e prepara um golpe carregado a cada três turnos.",
  "Rôdeur des tombes": "Espreitador dos túmulos",
  "Sa bouche est trop petite, son ventre trop grand. Rien ne le rassasie, il essaie quand même.": "Sua boca é pequena demais, sua barriga grande demais. Nada o sacia, mas ele tenta mesmo assim.",
  "Sa collection": "Coleção dele",
  "Sa compétence signature coûte {0} PA de moins.": "Sua habilidade assinatura custa {0} PA a menos.",
  "Sa frappe, puis ce qu’elle débloque en montant de niveau": "Seu golpe, e depois o que ele desbloqueia ao subir de nível",
  "Sa meute est morte de froid au pied du trône de glace. Il a survécu, seul, et il ne chasse plus pour manger.": "Sua matilha morreu de frio ao pé do trono de gelo. Ele sobreviveu, sozinho, e não caça mais para comer.",
  "Sa mort est cachée": "Sua morte está escondida",
  "Sa mort est dans une aiguille, l’aiguille dans un œuf, l’œuf dans un canard, le canard dans un coffre enterré.": "Sua morte está numa agulha, a agulha num ovo, o ovo num pato, o pato num baú enterrado.",
  "Sa mécanique": "Sua mecânica",
  "Sa paire <b>Céleste</b> le protégeait : {n0} <b>garde la main</b>.": "O par <b>Celestial</b> o protegia: {n0} <b>mantém a vez</b>.",
  "Sa première frappe de chaque combat fait +{0} % de dégâts et +{1} Brisure.": "Seu primeiro golpe de cada combate causa +{0}% de dano e +{1} de Quebra.",
  "Sa première frappe de chaque tour marque la cible : le prochain coup d’une autre de tes créatures fait +{0} % et +{1} Brisure.": "Seu primeiro golpe de cada turno marca o alvo: o próximo golpe de outra criatura sua causa +{0}% e +{1} de Quebra.",
  "Sa prochaine erreur ne lui fera pas perdre la main.": "O próximo erro dele não o fará perder a vez.",
  "Sa seule présence fait bouillir les rivières. Les pierres sont ses enfants, et elles se battent pour lui.": "Sua simples presença faz os rios ferverem. As pedras são seus filhos, e lutam por ele.",
  "Sa sœur Inanna descendit chez elle. Elle la suspendit à un crochet. Les dieux négocient encore.": "Sua irmã Inanna desceu até ela. Ela a pendurou num gancho. Os deuses ainda negociam.",
  "Sa toile ressemble à un chemin. C’est exactement le but.": "Sua teia parece um caminho. É exatamente essa a ideia.",
