  "Sceau : il protège d’une brisure. Gardien : arrêt forcé, tu encaisses tout de suite. Offrande : la prochaine carte compte double.": "Selo: protege de uma quebra. Guardião: parada forçada, você recebe na hora. Oferenda: a próxima carta vale o dobro.",
