  "Selon la Goétie, il sème la discorde et tue ceux qui l’invoquent sans précaution.": "Segundo a Goécia, ele semeia a discórdia e mata quem o invoca sem precaução.",
  "Selon l’appareil": "Conforme o aparelho",
