  "{e0}<b>À mi-vie : L’Écho des gardiens</b> L’Abysse rappelle les pouvoirs des gardiens vaincus : festin, tempête de givre, essaim, sentence, miroir, vœu.": "{e0}<b>À meia vida: O Eco dos guardiões</b> O Abismo invoca os poderes dos guardiões derrotados: banquete, tempestade de gelo, enxame, sentença, espelho, desejo.",
  "{e0}<b>À mi-vie : L’Écho des gardiens</b> {n0} rappelle les pouvoirs des gardiens vaincus : festin, tempête de givre, essaim, sentence, miroir, vœu.": "{e0}<b>À meia vida: O Eco dos guardiões</b> {n0} invoca os poderes dos guardiões derrotados: banquete, tempestade de gelo, enxame, sentença, espelho, desejo.",
  "{e0}<b>À mi-vie : Ruche vivante</b> Son Essaim empoisonne plus fort (+{0}), et à chaque tour elle se régénère de {1} % de ses PV par créature empoisonnée de ton équipe.": "{e0}<b>À meia vida: Colmeia viva</b> Seu Enxame envenena mais forte (+{0}), e a cada turno ela se regenera em {1}% dos PV por criatura envenenada da sua equipe.",
