  "{n0} met en vente {0} lots, un par manche : en général {1} créatures (de {2} à {3} points) et {4} malédictions (de −{5} à −{6}). Certaines salles changent les lots.": "{n0} põe à venda {0} lotes, um por rodada: em geral {1} criaturas (de {2} a {3} pontos) e {4} maldições (de −{5} a −{6}). Algumas salas mudam os lotes.",
