  "… l’écho se brise.": "… o eco se quebra.",
  "… l’écho se tait.": "… o eco se cala.",
  "…capturée. Les Secrètes ont les deux pouvoirs.": "…capturada. As Secretas têm os dois poderes.",
  "…et les deux cases changent de place. Toutes les deux poses, regarde où elles sont parties.": "…e as duas casas trocam de lugar. A cada duas jogadas, veja para onde elas foram.",
  "…et lui donne +{0}, pour toute la partie. Il faut au moins {1} cartes d’une même faction.": "…e lhe dá +{0} pela partida inteira. São necessárias pelo menos {1} cartas da mesma facção.",
