  "Choisis le booster et combien en ouvrir ({0} à {1}). Chaque joueur paie la même mise en éclats.": "Escolha o pacote e quantos abrir ({0} a {1}). Cada jogador paga a mesma aposta em fragmentos.",
  "Ton défi est ouvert à tous, ou envoyé à un ami. Il reste {0} h ; sinon ta mise t’est rendue.": "Seu desafio fica aberto a todos, ou é enviado a um amigo. Ele dura {0} h; senão, sua aposta é devolvida.",
  "Quand un joueur le relève, les boosters des deux joueurs s’ouvrent. Points par carte : Commune {0}, Peu commune {1}, Rare {2}, Hyper rare {3}, Mythique {4}, Secrète {5}, +{6} par finition.": "Quando um jogador aceita, os pacotes dos dois jogadores são abertos. Pontos por carta: Comum {0}, Incomum {1}, Rara {2}, Hiper-rara {3}, Mítica {4}, Secreta {5}, +{6} por acabamento.",
  "Le meilleur total remporte <b>toutes les cartes</b> : les siennes et celles de l’adversaire. Le perdant ne garde rien.": "O maior total leva <b>todas as cartas</b>: as suas e as do adversário. O perdedor não fica com nada.",
  "Égalité : chacun repart avec les cartes de ses boosters.": "Empate: cada um sai com as cartas dos próprios pacotes.",
  "Les boosters sont ouverts par le serveur : personne ne peut tricher sur les tirages.": "Os pacotes são abertos pelo servidor: ninguém pode trapacear nos sorteios.",
