  "Lancer le défi": "Lançar o desafio",
  "Relever le défi de <b>{name}</b> : {pack}.<br>Mise : <b>{stake} éclats</b>. Le meilleur total remporte toutes les cartes ; le perdant ne garde rien.": "Aceitar o desafio de <b>{name}</b>: {pack}.<br>Aposta: <b>{stake} fragmentos</b>. O maior total leva todas as cartas; o perdedor não fica com nada.",
  "Défier <b>{name}</b> : {pack}.<br>Mise : <b>{stake} éclats</b>, rendue s’il refuse ou ne relève pas le défi en {h} h.": "Desafiar <b>{name}</b>: {pack}.<br>Aposta: <b>{stake} fragmentos</b>, devolvida se o desafio for recusado ou não for aceito em {h} h.",
  "Lancer un défi ouvert à tous : {pack}.<br>Mise : <b>{stake} éclats</b>, rendue si personne ne le relève en {h} h.": "Lançar um desafio aberto a todos: {pack}.<br>Aposta: <b>{stake} fragmentos</b>, devolvida se ninguém aceitar em {h} h.",
