  "La suppression efface ton profil, ta sauvegarde en ligne et tes scores, et la partie de cet appareil.": "A exclusão apaga seu perfil, seu progresso online e suas pontuações, além da partida deste aparelho.",
  "Ta progression est liée à ton compte : si tu as déjà joué sur ce téléphone, ta partie y est envoyée dès que tu crées ton compte.": "Seu progresso está ligado à sua conta: se você já jogou neste celular, sua partida é enviada a ela assim que você criar sua conta.",
