  "Ta dernière progression n’a pas pu être envoyée sur ton compte (pas de réseau ?). Si tu te déconnectes maintenant, <b>elle sera perdue</b>.": "Seu último progresso não pôde ser enviado para sua conta (sem rede?). Se você sair agora, <b>ele será perdido</b>.",
