  "ABYSSAL peut t’envoyer une notification quand ton <b>booster gratuit du jour</b> t’attend, et avant la fin du délai quand c’est <b>à toi de jouer</b> contre un autre joueur.": "ABYSSAL pode enviar uma notificação quando seu <b>pacote grátis do dia</b> estiver esperando, e antes do fim do prazo quando for <b>sua vez</b> contra outro jogador.",
