  "Booster gratuit du jour (10 h) et rappel 2 h avant la fin du délai quand c’est à toi de jouer en ligne.": "Pacote grátis do dia (10 h) e lembrete 2 h antes do fim do prazo quando for sua vez online.",
  "Notifications refusées : autorise-les dans les Réglages du téléphone → ABYSSAL → Notifications.": "Notificações recusadas: permita-as nos Ajustes do celular → ABYSSAL → Notificações.",
  "Petites vibrations sur les coups, les victoires et les cartes rares. Dans l’app, le téléphone vibre vraiment ; sur le site web, l’iPhone ne vibre presque pas.": "Pequenas vibrações nos golpes, nas vitórias e nas cartas raras. No app, o celular vibra de verdade; no site, o iPhone quase não vibra.",
  "Tout révéler": "Revelar tudo",
  "En haut, « Contre un joueur » : affronte d’autres joueurs (au hasard ou un ami). Partie rapide : {0} s par coup, les deux joueurs connectés. Partie lente : {1} h par coup, chacun à son rythme. Coup pas joué à temps : partie perdue. Victoire : +{2} éclats et le classement du mois.": "No alto, “Contra um jogador”: enfrente outros jogadores (aleatório ou um amigo). Partida rápida: {0} s por jogada, os dois jogadores conectados. Partida lenta: {1} h por jogada, cada um no seu ritmo. Jogada não feita a tempo: partida perdida. Vitória: +{2} fragmentos e o ranking do mês.",
  "Choisis ta vitesse. Si tu ne joues pas ton coup à temps, <b>la partie est perdue</b>. La règle est tirée au hasard.": "Escolha sua velocidade. Se você não fizer sua jogada a tempo, <b>a partida está perdida</b>. A regra é sorteada.",
