  "En haut, « Contre un joueur » : une vente à deux contre un autre joueur (au hasard ou un ami), les mêmes lots pour les deux. Vous misez en même temps, en secret. Partie rapide : {0} s par mise ; partie lente : {1} h. Mise pas posée à temps : vente perdue. Victoire : +{2} éclats et le classement du mois.": "No alto, “Contra um jogador”: um leilão a dois contra outro jogador (aleatório ou um amigo), os mesmos lotes para os dois. Vocês dão lances ao mesmo tempo, em segredo. Partida rápida: {0} s por lance; partida lenta: {1} h. Lance não feito a tempo: leilão perdido. Vitória: +{2} fragmentos e o ranking do mês.",
  "Affronte d’autres joueurs : une vente à deux, en même temps.": "Enfrente outros jogadores: um leilão a dois, com lances ao mesmo tempo.",
  "Choisis ta vitesse. À chaque lot, vous misez en même temps et en secret ; si tu ne poses pas ton offrande à temps, <b>la vente est perdue</b>.": "Escolha sua velocidade. A cada lote, vocês dão lances ao mesmo tempo e em segredo; se você não colocar sua oferenda a tempo, <b>o leilão está perdido</b>.",
  "Les Enchères · en ligne": "O Leilão · online",
  "Réfléchit…": "Pensando…",
  "A misé": "Deu o lance",
  "Choisis ton offrande, en secret.": "Escolha sua oferenda, em segredo.",
  "Offrande {0}": "Oferenda {0}",
  "Offrir {0}": "Oferecer {0}",
  "Offrande : {n}": "Oferenda: {n}",
  "Ton offrande ({n}) est posée. En attente de <b>{name}</b>…": "Sua oferenda ({n}) foi colocada. Esperando <b>{name}</b>…",
  "<b>{name}</b> a déjà misé : à toi !": "<b>{name}</b> já deu o lance: sua vez!",
  "Tu remportes {n} lots": "Você leva {n} lotes",
  "{name} remporte {n} lots": "{name} leva {n} lotes",
  "{name} remporte le lot": "{name} leva o lote",
  "{name} hérite de la malédiction": "{name} herda a maldição",
  "Tu hérites de la malédiction": "Você herda a maldição",
  "Tu remportes le lot": "Você leva o lote",
  "Les deux offrandes s’annulent": "As duas oferendas se anulam",
  "Contre un ami": "Contra um amigo",
  "<b>Contre un ami</b>{e0}": "<b>Contra um amigo</b>{e0}",
  "En haut, « Contre un ami » : défie un de tes amis. Pas de récompense ici, seulement ton bilan de victoires et de défaites contre chacun. Partie rapide : {0} s par carte ; partie lente : {1} h. Coup pas joué à temps : partie perdue.": "No alto, “Contra um amigo”: desafie um dos seus amigos. Sem recompensa aqui, só seu histórico de vitórias e derrotas contra cada um. Partida rápida: {0} s por carta; partida lenta: {1} h. Jogada não feita a tempo: partida perdida.",
  "Entre amis : pour le plaisir, et pour ton bilan contre chacun.": "Entre amigos: pela diversão, e pelo seu histórico contra cada um.",
  "Défie un ami. Chaque fois que c’est à toi, tu as un temps limité pour retourner tes cartes : passé ce délai, <b>la partie est perdue</b>.": "Desafie um amigo. Cada vez que for sua vez, você tem um tempo limitado para virar suas cartas: depois desse prazo, <b>a partida está perdida</b>.",
  "Entre amis seulement : pas de récompense, juste ton bilan contre chacun.": "Só entre amigos: sem recompensa, só seu histórico contra cada um.",
  "Ton bilan contre tes amis": "Seu histórico contra seus amigos",
  "Pas encore de partie terminée contre un ami.": "Nenhuma partida encerrada contra um amigo ainda.",
