  "{name} se trompe… mais": "{name} erra… mas",
  "Sa paire <b>Céleste</b> le protégeait : {name} <b>garde la main</b>.": "O par <b>Celestial</b> o protegia: {name} <b>continua com a vez</b>.",
  "{name} a échangé ces deux cartes de place.": "{name} trocou estas duas cartas de lugar.",
  "{name} montre cette carte à tout le monde.": "{name} mostra esta carta para todos.",
