  "Égalité de points : la dernière paire décide.": "Empate em pontos: o último par decide.",
  "Toi seul vois cette carte : retiens-la !": "Só você vê esta carta: memorize-a!",
  "Tout le monde voit cette carte.": "Todo mundo vê esta carta.",
  "Les deux cartes ont échangé leur place.": "As duas cartas trocaram de lugar.",
