  "Un défi reçu aux Cryptes": "Um desafio recebido nas Criptas",
  "{n} défis reçus aux Cryptes": "{n} desafios recebidos nas Criptas",
  "Ton équipe : <b>{0} créatures au combat</b> et <b>{1} en réserve</b>. Chaque carte a un <b>rôle</b> (icône en haut à gauche), son <b>attaque</b> et ses <b>PV</b>. Mets au combat tes créatures les plus fortes : il n’y a pas de limite. Les <b>cendres</b> font monter une créature de niveau : brûle tes doublons dans la <b>Fournaise</b> pour en gagner.": "Sua equipe: <b>{0} criaturas em combate</b> e <b>{1} na reserva</b>. Cada carta tem uma <b>função</b> (ícone no canto superior esquerdo), seu <b>ataque</b> e seus <b>PV</b>. Coloque em combate suas criaturas mais fortes: não há limite. As <b>cinzas</b> sobem o nível de uma criatura: queime suas repetidas na <b>Fornalha</b> para ganhá-las.",
  "Un jeu de cartes à part, sans PV ni attaque : chaque carte a <b>quatre valeurs</b>, une par côté. Bats les adversaires dans l’ordre pour débloquer les suivants : la <b>première victoire</b> contre chacun donne un coffre (bois, fer, or puis abyssal selon son rang). Après Ilda, relève aussi le <b>défi du jour</b>. Compose ta main de {0} cartes avec <b>Composer ma main</b>.<br><br>Une fois par jour, une victoire te laisse garder une carte adverse : le <b>Butin</b>.": "Um jogo de cartas à parte, sem PV nem ataque: cada carta tem <b>quatro valores</b>, um por lado. Vença os adversários em ordem para desbloquear os seguintes: a <b>primeira vitória</b> contra cada um dá um baú (madeira, ferro, ouro e depois abissal conforme o nível dele). Depois de Ilda, encare também o <b>desafio do dia</b>. Monte sua mão de {0} cartas com <b>Montar minha mão</b>.<br><br>Uma vez por dia, uma vitória deixa você ficar com uma carta adversária: o <b>Espólio</b>.",
  "Profil d’un joueur": "Perfil de um jogador",
  "Ce joueur est introuvable.": "Este jogador não foi encontrado.",
  "{name} n’a pas encore partagé son profil : il apparaîtra quand il aura ouvert le jeu à jour.": "{name} ainda não compartilhou o perfil: ele vai aparecer quando abrir o jogo atualizado.",
