  "gratuite": "gratuita",
  "à débloquer": "a desbloquear",
  "Débloque la colonne de droite : cadres peints, dos de cartes et titres exclusifs à cette saison.": "Desbloqueia a coluna da direita: molduras pintadas, versos de carta e títulos exclusivos desta temporada.",
