  "<b>{0} ×</b><small>booster standard</small>": "<b>{0} ×</b><small>pacote padrão</small>",
  "La voie de gauche se gagne en jouant. La voie enluminée se débloque une fois par saison avec des obsidiennes : seulement des cadres peints, des titres et des dos de cartes, jamais de puissance.": "A trilha da esquerda é ganha jogando. A trilha iluminada é desbloqueada uma vez por temporada com obsidianas: só molduras pintadas, títulos e versos de carta, nunca poder.",
