  "Finition Scellée": "Acabamento Selado",
  "Une finition achetée se pose sur autant de cartes que tu veux, une par carte. Elle ne change rien à leurs valeurs.": "Um acabamento comprado pode ser colocado em quantas cartas você quiser, um por carta. Ele não muda nada nos valores delas.",
  "<b>Pack du Fondateur</b> <small>Vendu une seule fois. Le cadre et le dos de cartes du Fondateur, le titre « Fondateur » (badge au classement) et {0} obsidiennes.</small>": "<b>Pacote do Fundador</b> <small>Vendido uma única vez. A moldura e o verso de carta do Fundador, o título “Fundador” (selo no ranking) e {0} obsidianas.</small>",
  "Pendant l'aperçu, tout achat en euros est simulé : aucun paiement. Rien ici ne rend tes créatures plus fortes.": "Durante a prévia, toda compra em dinheiro é simulada: nenhum pagamento. Nada aqui deixa suas criaturas mais fortes.",
