  "{e0}Collection": "{e0}Coleção",
  "Collection": "Coleção",
  "<b>Sa mécanique</b> Il annonce « Dévorer » : il arrache des PV à ta créature la plus vigoureuse et s’en nourrit. Chaque festin réussi le rend plus fort.": "<b>Sua mecânica</b> Ele anuncia “Devorar”: arranca PV da sua criatura mais vigorosa e se alimenta deles. Cada banquete bem-sucedido o deixa mais forte.",
  "{e0}<b>À mi-vie : {n0}</b> Il avale ta créature la plus vigoureuse : elle quitte le combat et se fait digérer à chaque tour. Brise-le (ou abats-le) pour la libérer.": "{e0}<b>À meia vida: {n0}</b> Ele engole sua criatura mais vigorosa: ela sai do combate e é digerida a cada turno. Quebre-o (ou abata-o) para libertá-la.",
  "<b>Pour le contrer</b> Gèle-le ou brise-le pendant qu’il prépare son festin. Un {n0} réduit la morsure.": "<b>Para combatê-lo</b> Congele-o ou quebre-o enquanto ele prepara o banquete. Um {n0} reduz a mordida.",
  "Pause": "Pausa",
  "{e0}<em>Parasite</em>": "{e0}<em>Parasita</em>",
  "Parasite": "Parasita",
  "{e0}<b>{0}</b><small>→ {n0}</small>": "{e0}<b>{0}</b><small>→ {n0}</small>",
  "Infernal": "Infernal",
  "Metatron": "Metatron",
  "<b>Esquive !</b>": "<b>Esquiva!</b>",
  "Arrache des PV à la cible (plus d’une fois et demie sa force) et s’en nourrit. Chaque festin réussi lui donne +{0} ATQ (+{1} en phase {2}). Gel ou Brisure l’interrompent. Renforcée par ses serviteurs : +{3} %.": "Arranca PV do alvo (mais de uma vez e meia sua força) e se alimenta deles. Cada banquete bem-sucedido dá +{0} ATQ (+{1} na fase {2}). Gelo ou Quebra o interrompem. Reforçado por seus servos: +{3}%.",
  "{e0}<b>Dévorer +{0} %</b><small>à son tour</small>": "{e0}<b>Devorar +{0}%</b><small>no turno dele</small>",
  "Dévorer +{0} %": "Devorar +{0}%",
  "Syn.": "Sin.",
  "Empoisonnement : Frappe et empoisonne la cible (+{0} poison).": "Envenenamento: golpeia e envenena o alvo (+{0} veneno).",
