  "{e0} Dévorer ! <small>Maintiens le doigt, relâche dans l’or · sur le trait blanc : parade</small>": "{e0} Devorar! <small>Segure o dedo, solte no dourado · na linha branca: defesa</small>",
  "Dévorer !": "Devorar!",
  "{e0}<b>Dévorer !</b>": "{e0}<b>Devorar!</b>",
  "<b>Sa mécanique</b> Un tour sur deux, il rend un Verdict : à ton tour suivant, une action est interdite à toute ton équipe (attaquer, utiliser une compétence, ou se défendre).": "<b>Sua mecânica</b> A cada dois turnos, ele dá um Veredito: no seu próximo turno, uma ação fica proibida para toda a sua equipe (atacar, usar uma habilidade ou se defender).",
  "{e0}<b>À mi-vie : Sentence finale</b> Ses Verdicts tombent toujours un tour sur deux, et ses coups chargés frappent plus fort.": "{e0}<b>À meia vida: Sentença final</b> Seus Veredictos continuam caindo a cada dois turnos, e seus golpes carregados batem mais forte.",
